(()=>{
const qs=selector=>document.querySelector(selector);
const navToggle=qs('.nav-toggle');navToggle?.addEventListener('click',()=>{const open=navToggle.getAttribute('aria-expanded')!=='true';navToggle.setAttribute('aria-expanded',open);navToggle.setAttribute('aria-label',open?'Close navigation':'Open navigation');qs('.main-nav').classList.toggle('open',open);});
const config=window.AUREA_SITE_CONFIG||{};if(/^G-[A-Z0-9]{5,20}$/.test(config.googleAnalyticsMeasurementId||'')){window.dataLayer=window.dataLayer||[];window.gtag=function(){window.dataLayer.push(arguments);};window.gtag('js',new Date());window.gtag('config',config.googleAnalyticsMeasurementId);const script=document.createElement('script');script.async=true;script.src='https://www.googletagmanager.com/gtag/js?id='+encodeURIComponent(config.googleAnalyticsMeasurementId);document.head.append(script);}
const ga=(event)=>{if(window.gtag)window.gtag(event==='form_submission'?'event':'event',event==='form_submission'?'generate_lead':'contact_button_click',{page_path:location.pathname});};
document.addEventListener('click',event=>{const link=event.target.closest('[data-contact-action]');if(link){ga('contact_button_click');fetch('/api/actions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'contact_button_click',page:location.pathname}),keepalive:true}).catch(()=>{});}});
const dialog=qs('#contact-demo');document.querySelectorAll('.demo-contact').forEach(button=>button.addEventListener('click',()=>dialog.showModal()));qs('.dialog-close')?.addEventListener('click',()=>dialog.close());dialog?.addEventListener('click',event=>{if(event.target===dialog)dialog.close();});
const search=qs('#catalog-search');if(search){const grid=qs('.catalog-products'),cards=[...grid.children],original=[...cards],params=new URLSearchParams(location.search);let collection=['Women','Men','Unisex'].includes(params.get('collection'))?params.get('collection'):'All';const families=[...document.querySelectorAll('input[name=family]')],price=qs('#price-filter'),sort=qs('#catalog-sort');families.forEach(input=>input.checked=input.value===params.get('family'));const buttons=[...document.querySelectorAll('[data-collection-filter]')];const update=()=>{const selected=families.filter(input=>input.checked).map(input=>input.value);const query=search.value.toLowerCase().trim();const filtered=cards.filter(card=>(collection==='All'||card.dataset.collection===collection)&&(!selected.length||selected.includes(card.dataset.family))&&Number(card.dataset.price)<=Number(price.value)&&card.textContent.toLowerCase().includes(query));buttons.forEach(button=>button.classList.toggle('active',button.dataset.collectionFilter===collection));cards.forEach(card=>card.hidden=!filtered.includes(card));let ordered=[...filtered];if(sort.value==='price-low')ordered.sort((a,b)=>a.dataset.price-b.dataset.price);if(sort.value==='price-high')ordered.sort((a,b)=>b.dataset.price-a.dataset.price);if(sort.value==='name')ordered.sort((a,b)=>a.dataset.name.localeCompare(b.dataset.name));if(sort.value==='featured')ordered.sort((a,b)=>original.indexOf(a)-original.indexOf(b));ordered.forEach(card=>grid.append(card));qs('#catalog-count').textContent=`Showing ${filtered.length} of ${cards.length} fragrances`;qs('#catalog-empty').hidden=filtered.length>0;qs('#price-label').textContent='₱'+price.value;};buttons.forEach(button=>button.addEventListener('click',()=>{collection=button.dataset.collectionFilter;update();}));[search,price,...families].forEach(input=>input.addEventListener('input',update));sort.addEventListener('change',update);qs('.clear-filters').addEventListener('click',()=>{collection='All';families.forEach(input=>input.checked=false);price.value=900;search.value='';sort.value='featured';update();});update();}
const form=qs('#inquiry-form');if(form){const params=new URLSearchParams(location.search);if([...form.elements.interest.options].some(option=>option.value===params.get('fragrance')))form.elements.interest.value=params.get('fragrance');form.addEventListener('submit',async event=>{event.preventDefault();if(!form.reportValidity())return;const button=form.querySelector('[type=submit]'),status=qs('#form-status');button.disabled=true;button.textContent='Sending…';status.textContent='';try{const data=Object.fromEntries(new FormData(form));data.consent=form.elements.consent.checked;const response=await fetch('/api/inquiries',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Please try again.');status.textContent=result.message;ga('form_submission');form.reset();}catch(error){status.textContent=error.message;}finally{button.disabled=false;button.textContent='Send Inquiry';}});}
})();
